type WechatMiniProgramPublishTask struct {
	// Task ID.
	TaskId *string `json:"TaskId,omitnil,omitempty" name:"TaskId"`

	// Task status. Valid values:
	// WAITING: waiting.
	// PROCESSING: Processing;
	// FINISH: completed.
	Status *string `json:"Status,omitnil,omitempty" name:"Status"`

	// Error code.
	// <li>0: success;</li>
	// <li>Other value: Failed.</li>
	ErrCode *int64 `json:"ErrCode,omitnil,omitempty" name:"ErrCode"`

	// Error message.
	Message *string `json:"Message,omitnil,omitempty" name:"Message"`

	// Video file ID for publishing.
	FileId *string `json:"FileId,omitnil,omitempty" name:"FileId"`

	// Transcoding template ID for the published video. 0 represents the original video.
	SourceDefinition *uint64 `json:"SourceDefinition,omitnil,omitempty" name:"SourceDefinition"`

	// WeChat Mini Program Video Publishing status. Parameter Value:
	// <li>Pass: published successfully;</li>
	// <li>Failed: Release failure;</li>
	// <li>Rejected: The audio and video moderation failed to pass.</li>
	PublishResult *string `json:"PublishResult,omitnil,omitempty" name:"PublishResult"`
}

type WechatMiniProgramPublishTaskInput struct {
	// Transcoding template ID for the published video. 0 represents the original video.
	SourceDefinition *uint64 `json:"SourceDefinition,omitnil,omitempty" name:"SourceDefinition"`
}

type WechatPublishTask struct {
	// Task ID.
	TaskId *string `json:"TaskId,omitnil,omitempty" name:"TaskId"`

	// Task status. Valid values:
	// WAITING: waiting.
	// PROCESSING: Processing;
	// FINISH: completed.
	Status *string `json:"Status,omitnil,omitempty" name:"Status"`

	// Error code.
	// <li>0: success;</li>
	// <li>Other value: unsuccessful.</li>
	ErrCode *int64 `json:"ErrCode,omitnil,omitempty" name:"ErrCode"`

	// Error message.
	Message *string `json:"Message,omitnil,omitempty" name:"Message"`

	// Video file ID for publishing.
	FileId *string `json:"FileId,omitnil,omitempty" name:"FileId"`

	// Template ID for publishing on WeChat.
	Definition *uint64 `json:"Definition,omitnil,omitempty" name:"Definition"`

	// Transcoding template ID of the published video. 0 represents the original video.
	SourceDefinition *uint64 `json:"SourceDefinition,omitnil,omitempty" name:"SourceDefinition"`

	// WeChat publishing status. Valid values:
	// <li>FAIL: Failed;</li>
	// <li>SUCCESS: successful;</li>
	// <li>AUDITNOTPASS: failed to pass moderation;</li>
	// <li>NOTTRIGGERED: Publishing on WeChat has not been initiated.</li>
	WechatStatus *string `json:"WechatStatus,omitnil,omitempty" name:"WechatStatus"`

	// WeChat Vid.
	WechatVid *string `json:"WechatVid,omitnil,omitempty" name:"WechatVid"`

	// WeChat address.
	WechatUrl *string `json:"WechatUrl,omitnil,omitempty" name:"WechatUrl"`
}